;/* WarFront diagnostic overlay v4: isolated from original HTML/bootstrap */
(()=>{
  try {
    if(window.__warfrontFpsV4)return;
    window.__warfrontFpsV4=true;
    let last=performance.now(),count=0,elapsed=0,worst=0,fps=0,avg=0;
    let panel=null;
    const attach=()=>{
      if(!document.body)return;
      if(!panel){
        panel=document.createElement('div');
        panel.id='warfront-fps-v4';
        panel.style.cssText='position:fixed!important;top:8px!important;left:8px!important;z-index:2147483647!important;background:rgba(12,18,17,.85)!important;color:#fff!important;font:700 15px monospace!important;padding:7px 10px!important;border:1px solid #a9b49d!important;border-radius:4px!important;pointer-events:none!important;white-space:pre!important;display:block!important;visibility:visible!important;opacity:1!important;';
      }
      if(!panel.isConnected)document.body.appendChild(panel);
    };
    const tick=(now)=>{
      const delta=Math.min(1000,Math.max(0,now-last));last=now;
      count++;elapsed+=delta;worst=Math.max(worst,delta);
      if(elapsed>=1000){fps=Math.round(count*1000/elapsed);avg=(elapsed/count).toFixed(1);count=0;elapsed=0;worst=0;}
      if(count%30===0||fps===0){attach();if(panel)panel.textContent='FPS '+fps+' | '+avg+' ms';}
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    setInterval(attach,1500);
  }catch(err){console.warn('WarFront FPS overlay disabled',err);}
})();
